            margin-top: 0;
        }
        .map-link {
            display: block;
            margin: 10px 0;
            color: #007bff;
            text-decoration: none;
        }
        .message-form {
            margin: 20px 0;
            padding: 15px;
            background: white;
            border-radius: 5px;
            text-align: center;
        }
        .message-form input {
            padding: 10px;
            width: 100%;
            margin-bottom: 10px;
        }
        .message-form button {
            padding: 10px;
            width: 100%;
            background: #007bff;
            color: white;
            border: none;
            border-radius: 5px;
        }
        .message-form button:hover {
            background: #0056b3;
        }
    </style>
</head>
<body>
    <header>
        <h1>Contact Us</h1>
    </header>
    <div class="branches">
        <div class="branch">
            <h2>Branch 1</h2>
