<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Mama Njeri's Story</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            margin: 0;
            padding: 0;
            background: #f4f4f4;
            color: #333;
        }
        header {
            background: #ff6f61;
            color: white;
            text-align: center;
            padding: 1em;
        }
        h1 {
            margin: 0;
            font-size: 2em;
        }
        .section {
            max-width: 800px;
            margin: 2em auto;
            padding: 1em;
            background: white;
            border-radius: 10px;
            box-shadow: 0 0 10px rgba(0,0,0,0.1);
        }
        .story {
            background: #fff;
            padding: 1em;
            border-radius: 10px;
            box-shadow: 0 0 5px rgba(0,0,0,0.1);
        }
        .team {
            background: #fff;
            padding: 1em;
            border-radius: 10px;
            box-shadow: 0 0 5px rgba(0,0,0,0.1);
        }
        .photos {
            background: #fff;
            padding: 1em;
            border-radius: 10px;
            box-shadow: 0 0 5px rgba(0,0,0,0.1);
        }
        .photo {
            width: 100%;
            max-width: 400px;
            margin: 1em auto;
            display: block;
            border: 1px solid #ccc;
            border-radius: 5px;
            box-shadow: 0 0 5px rgba(0,0,0,0.1);
        }
        footer {
            text-align: center;
            padding: 1em;
            background: #ff6f61;
            color: white;
            font-size: 0.9em;
        }
    </style>
